import { defineConfig, devices } from '@playwright/test'
import { resolve } from 'node:path'

// The e2e harness spawns the built ./explorer binary twice:
//
//   • Project "repo"     — pointed at testdata/sample-repo (generated by
//     `make sample-repo`). Hosts the spec tests that exercise the git-reader
//     surface end to end.
//   • Project "no-repo"  — pointed at testdata/ (no .git at top level). Hosts
//     the tests that assert git affordances disappear and the /git/* routes
//     fall through to the NoGitRepo placeholder.
//
// Each project uses a unique port via `webServer` so the two binaries can run
// concurrently. `cwd` is the repo root so the relative paths inside binary
// CLI args resolve as the developer would expect.

const repoRoot = resolve(__dirname, '..')

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  workers: 1,
  reporter: process.env.CI ? 'github' : 'list',
  use: {
    headless: true,
    trace: 'on-first-retry',
  },

  projects: [
    {
      name: 'repo',
      testIgnore: '**/no-repo.spec.ts',
      use: {
        ...devices['Desktop Chrome'],
        baseURL: 'http://127.0.0.1:8717',
      },
    },
    {
      name: 'no-repo',
      testMatch: '**/no-repo.spec.ts',
      use: {
        ...devices['Desktop Chrome'],
        baseURL: 'http://127.0.0.1:8718',
      },
    },
  ],

  webServer: [
    {
      // Spawn the built binary against the sample-repo fixture for the main project.
      command: `./explorer testdata/sample-repo --host 127.0.0.1 --port 8717`,
      cwd: repoRoot,
      url: 'http://127.0.0.1:8717/api/git/info',
      reuseExistingServer: !process.env.CI,
      timeout: 30_000,
    },
    {
      // Spawn against ./testdata (non-repo) for the no-repo project.
      command: `./explorer testdata --host 127.0.0.1 --port 8718`,
      cwd: repoRoot,
      url: 'http://127.0.0.1:8718/api/git/info',
      reuseExistingServer: !process.env.CI,
      timeout: 30_000,
    },
  ],
})
